  rationale STRING,
  mapped_by STRING NOT NULL DEFAULT 'catalog',
  manual BOOLEAN NOT NULL DEFAULT false,
  mapped_at TIMESTAMP NOT NULL DEFAULT current_timestamp()
) TBLPROPERTIES ('delta.feature.allowColumnDefaults' = 'supported', 'delta.enableDeletionVectors' = 'true', 'delta.enableRowTracking' = 'true');

