CREATE OR REPLACE VIEW ${catalog}.${schema}.asset_status_by_account AS SELECT a.id AS account_id, da.id AS data_asset_id, COALESCE(s.ingestion_status, CAST('not_started' AS STRING)) AS ingestion_status, COALESCE(s.local_name, da.module) AS display_name, COALESCE(s.owning_lob_id, da.owning_lob_id) AS owning_lob_id, COALESCE(s.ingest_cost_low, da.ingest_cost_low) AS ingest_cost_low, COALESCE(s.ingest_cost_high, da.ingest_cost_high) AS ingest_cost_high, COALESCE(s.is_user_edited, FALSE) AS is_user_edited, (NOT s.account_id IS NULL) AS has_account_row FROM ((accounts AS a CROSS JOIN data_assets AS da) LEFT JOIN account_asset_status AS s ON (((s.account_id = a.id) AND (s.data_asset_id = da.id))));
